    var eocd = data.length - 4;
    while (rUi(data, eocd) != 101010256) {
      eocd--;
    }
    var o = eocd;
    o += 4; // sign  = 0x06054b50
    o += 4; // disks = 0;
    var cnu = rUs(data, o);
    o += 2;
    var cnt = rUs(data, o);
    o += 2;
    var csize = rUi(data, o);
    o += 4;
    var coffs = rUi(data, o);
    o += 4;
    o = coffs;
